import FieldSet from "@marko-ui/shadcn/ui/field/field-set.marko";
import FieldLegend from "@marko-ui/shadcn/ui/field/field-legend.marko";
import FieldGroup from "@marko-ui/shadcn/ui/field/field-group.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldError from "@marko-ui/shadcn/ui/field/field-error.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

export type ValidatableControl = { validity: ValidityState; validationMessage: string; name: string };

static function isValidatable(control: Element): control is Element & ValidatableControl {
  return "validity" in control && "validationMessage" in control && "name" in control;
}

<const/messageFor=(control: ValidatableControl) => (control.validity.valid ? undefined : control.validationMessage)/>

<let/errors=({} as Record<string, string[] | undefined>)/>
<let/submitted=false/>

<const/validateField=(control: HTMLInputElement) => {
  const message = messageFor(control);
  errors = { ...errors, [control.name]: message ? [message] : undefined };
}/>

<const/validateForm=(form: HTMLFormElement) => {
  const next: Record<string, string[] | undefined> = {};
  let valid = true;

  for (const control of form.elements) {
    if (!isValidatable(control) || !control.name) continue;
    const message = messageFor(control);
    if (message) {
      next[control.name] = [message];
      valid = false;
    }
  }

  errors = next;
  return valid;
}/>

<form
  novalidate
  class="w-full max-w-sm"
  onSubmit(event, form) {
    event.preventDefault();
    submitted = validateForm(form);
  }
>
  <FieldSet>
    <FieldLegend>Create an account</FieldLegend>
    <FieldDescription>All fields are required.</FieldDescription>
    <FieldGroup>
      <Field invalid=!!errors.username>
        <FieldLabel for="signup-username">Username</FieldLabel>
        <TextInput
          id="signup-username"
          name="username"
          required
          minlength=3
          maxlength=20
          pattern="[A-Za-z0-9_]+"
          autocomplete="username"
          aria-invalid=(errors.username ? "true" : undefined)
          aria-describedby=(errors.username ? "signup-username-error" : "signup-username-description")
          onBlur(event, control) { validateField(control); }
        />
        <FieldDescription id="signup-username-description">
          3-20 characters: letters, numbers and underscores.
        </FieldDescription>
        <FieldError id="signup-username-error" errors=errors.username/>
      </Field>

      <Field invalid=!!errors.email>
        <FieldLabel for="signup-email">Email</FieldLabel>
        <TextInput
          id="signup-email"
          name="email"
          type="email"
          required
          autocomplete="email"
          aria-invalid=(errors.email ? "true" : undefined)
          aria-describedby=(errors.email ? "signup-email-error" : undefined)
          onBlur(event, control) { validateField(control); }
        />
        <FieldError id="signup-email-error" errors=errors.email/>
      </Field>

      <Field invalid=!!errors.password>
        <FieldLabel for="signup-password">Password</FieldLabel>
        <TextInput
          id="signup-password"
          name="password"
          type="password"
          required
          minlength=8
          pattern=".*[0-9].*"
          autocomplete="new-password"
          aria-invalid=(errors.password ? "true" : undefined)
          aria-describedby=(errors.password ? "signup-password-error" : "signup-password-description")
          onBlur(event, control) { validateField(control); }
        />
        <FieldDescription id="signup-password-description">
          At least 8 characters and one number.
        </FieldDescription>
        <FieldError id="signup-password-error" errors=errors.password/>
      </Field>

      <Button type="submit">Create account</Button>

      <if=submitted>
        <p class="text-sm font-medium text-primary">Account created. Welcome aboard!</p>
      </if>
    </FieldGroup>
  </FieldSet>
</form>
